select * from pcd_directory_tree_table
where node_id=#{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
    or node_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    or (#{personalSpace}=true and node_space_id is null
        and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}));

SELECT * FROM pcd_directory_tree_table
WHERE node_parent_id IS NULL
  AND node_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_status IN ('active', 'lock')
ORDER BY node_create_time ASC
LIMIT 1;


SELECT * FROM pcd_directory_tree_table
WHERE node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND (node_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
       OR (#{personalSpace}=true AND node_space_id IS NULL))
  AND node_status IN ('active', 'lock')
LIMIT 1;

SELECT *
FROM pcd_directory_tree_table
WHERE node_id = #{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND (
      node_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
      OR (#{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} IS NULL
          AND node_space_id IS NULL)
  )
  AND node_status IN ('active', 'lock')
LIMIT 1;

SELECT * FROM pcd_directory_tree_table
WHERE node_parent_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_status IN ('active', 'lock')
ORDER BY node_name ASC;

SELECT *
FROM pcd_directory_tree_table
WHERE node_parent_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND (
      node_space_id = #{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
      OR (#{space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} IS NULL
          AND node_space_id IS NULL)
  )
  AND node_status IN ('active', 'lock')
ORDER BY node_name ASC;



select * from pcd_directory_tree_table
where node_parent_id=#{node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  and ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
    or node_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    or (#{personalSpace}=true and node_space_id is null
        and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}))
  and node_status not in ('trashed', 'deleted');

