mapper.select:
SELECT COUNT(1)
FROM pcd_directory_tree_table
WHERE node_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_status IN ('active', 'pending');



SELECT (
    (SELECT COUNT(1) FROM pcd_directory_tree_table
     WHERE node_parent_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
       AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
         OR node_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
         OR (#{personalSpace}=true and node_space_id is null
             and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}))
       AND node_status IN ('active', 'pending'))
    +
    (SELECT COUNT(1) FROM pcd_file_info_table
     WHERE file_node_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
       AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and file_author_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
         OR file_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
         OR (#{personalSpace}=true and file_space_id is null
             and file_author_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}))
       AND file_status = 'active')
) AS total;



SELECT * FROM pcd_directory_tree_table
WHERE node_parent_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND node_name = #{name}
  AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
    OR node_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    OR (#{personalSpace}=true and node_space_id is null
        and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}))
  AND node_status IN ('active', 'pending')
LIMIT 1;



SELECT * FROM pcd_directory_tree_table
WHERE node_name = #{name}
  AND node_parent_id = #{parent_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND ((#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler} is null and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler})
    OR node_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    OR (#{personalSpace}=true and node_space_id is null
        and node_user_id=#{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}))
  AND node_status NOT IN ('trashed', 'deleted')
LIMIT 1;
